fn rolling_max(numbers: Vec<i32>) -> Vec<i32> {
    let mut result = Vec::with_capacity(numbers.len());
    let mut current_max = None;

    for &num in &numbers {
        current_max = match current_max {
            Some(max_val) => Some(if num > max_val { num } else { max_val }),
            None => Some(num),
        };
        // Safe to unwrap because current_max is Some here
        result.push(current_max.unwrap());
    }

    result
}